CREATE VIEW v1360 AS SELECT ST_OVERLAPS(ST_GEOMETRYFROMTEXT('geometrycollection(polygon((0 0, 2 0, 2 1, 0 1, 0 0)))'), ST_GEOMETRYFROMTEXT('geometrycollection(polygon((1 0, 3 0, 3 1, 1 1, 1 0)))')), ST_ASTEXT(ST_CONVEXHULL(ST_GEOMFROMTEXT('+++++++++'))), ST_ASTEXT(ST_INTERSECTION(ST_GEOMFROMTEXT('POLYGON((0 0, 50 45, 40 50, 0 0))'), ST_GEOMFROMTEXT('LINESTRING(-10 -10, 200 200)'))), SUM(x5.v1074), SUM(x5.v1074), SUM(CASE WHEN x5.v1074 IS NULL THEN 0.00 ELSE x5.v1074 END) FROM v1073 AS x5 GROUP BY x5.v1074 COLLATE ucs2_turkish_ci